package com.xpe.mobile.preview;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public final class PhiraBackgroundBlurTest {
    @Test public void pixelsMatchOriginalRustFastblurIncludingItsBufferOrder() {
        // Generated by unmodified fastblur 0.1.1, Cargo.lock's exact prpr dependency.
        // Pattern: R=(17x+3y)%256, G=(x*x+11y)%256, B=((x/7+y/9)%2)*255.
        assertReference(173,137,50,0xb2f2058c44760a1aL);
        assertReference(127,119,25,0xafdf5e0a7301197eL);
        assertReference(64,64,12.5f,0x06e9138c4eba6c4bL);
    }

    @Test public void tinyImagesUseClampedEdgesAndRgbBackgroundIsOpaque() {
        for (int[] size : new int[][]{{1,1},{2,3},{9,7},{51,53}}) {
            int[] pixels = new int[size[0]*size[1]];
            Arrays.fill(pixels,0x30123456);
            PhiraBackgroundBlur.blurInPlace(pixels,size[0],size[1],50);
            for (int pixel : pixels) assertEquals(0xff123456,pixel);
        }
    }

    @Test public void zeroSigmaKeepsRgbAndInvalidBuffersAreRejected() {
        int[] pixels = {0x30123456,0x00abcdef};
        PhiraBackgroundBlur.blurInPlace(pixels,2,1,0);
        assertArrayEquals(new int[]{0xff123456,0xffabcdef},pixels);
        assertThrows(IllegalArgumentException.class, () -> PhiraBackgroundBlur.blurInPlace(pixels,3,1,50));
        assertThrows(IllegalArgumentException.class, () -> PhiraBackgroundBlur.blurInPlace(pixels,2,1,Float.NaN));
    }

    @Test public void fullHdBackgroundCanBePreparedOnceOffTheDrawingPath() {
        int[] pixels = pattern(1920,1080);
        long before = System.nanoTime();
        PhiraBackgroundBlur.blurInPlace(pixels,1920,1080,50);
        System.out.println("Full HD cached background blur: " + (System.nanoTime()-before)/1e6 + " ms");
        for (int pixel : pixels) assertEquals(255,pixel >>> 24);
    }

    private static void assertReference(int width,int height,float sigma,long expected) {
        int[] pixels = pattern(width,height);
        PhiraBackgroundBlur.blurInPlace(pixels,width,height,sigma);
        long hash = 0xcbf29ce484222325L;
        for (int pixel : pixels) {
            for (int shift : new int[]{16,8,0}) hash = (hash ^ (pixel >>> shift & 255)) * 0x100000001b3L;
        }
        assertEquals("Rust RGB output " + width + "x" + height,expected,hash);
    }

    private static int[] pattern(int width,int height) {
        int[] pixels = new int[width*height];
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                pixels[y*width+x] = 0xff000000 | (((x*17+y*3)%256) << 16)
                        | (((x*x+y*11)%256) << 8) | (((x/7+y/9)%2)*255);
            }
        }
        return pixels;
    }
}
